import numpy as np
from scipy.optimize import fsolve
import warnings
warnings.filterwarnings('ignore')

sqrt5 = np.sqrt(5)

def solve_3point_num(k, l, m, n):
    """Solve for u, v, w given multiplicities k, l, m numerically."""
    # From eq1: w = -(ku + lv)/m
    # Substitute into eq2 and eq3, get 2 equations in u, v
    def equations(vars):
        u, v = vars
        w = -(k*u + l*v) / m
        eq2 = k*u**2 + l*v**2 + m*w**2 - n
        eq3 = k*u**3 + l*v**3 + m*w**3 + n
        return [eq2, eq3]

    results = []
    # Try multiple initial guesses
    for u0 in np.linspace(-3, 3, 20):
        for v0 in np.linspace(-3, 3, 20):
            if abs(u0 - v0) < 0.1:
                continue
            try:
                sol = fsolve(equations, [u0, v0], full_output=True)
                x, info, ier, msg = sol
                if ier == 1:
                    u, v = x
                    w = -(k*u + l*v) / m
                    vals = sorted([u, v, w])
                    R = vals[2] - vals[0]
                    if R > 2.0 and R < 10:  # reasonable range
                        # Check it's a real solution
                        res = equations([u, v])
                        if abs(res[0]) < 1e-8 and abs(res[1]) < 1e-8:
                            results.append((R, vals))
            except:
                pass

    # Deduplicate
    unique = []
    for R, vals in results:
        is_dup = False
        for R2, vals2 in unique:
            if abs(R - R2) < 1e-6:
                is_dup = True
                break
        if not is_dup:
            unique.append((R, vals))
    return unique

for n in range(4, 25):
    best_R = float('inf')
    best_config = None

    for k in range(1, n-1):
        for l in range(1, n-k):
            m = n - k - l
            if m < 1:
                continue
            results = solve_3point_num(k, l, m, n)
            for R, vals in results:
                if R > 0 and R < best_R:
                    best_R = R
                    best_config = (k, l, m, vals)

